using System;
using System.IO;
using System.Xml;
using System.Reflection;
using System.Globalization;
class Preferences {
 public string Folder="";public int Category,Preset=-1;public int LayoutMode,Mp3Kbps=192;public int[] Formats=new int[5];public GifOptions Gif=new GifOptions();public static string PathOverride{get;set;}
 public static string DefaultPath{get{return PathOverride??Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Forma","settings.xml");}}
 public static Preferences Load(string path){var p=new Preferences();try{var d=new XmlDocument{XmlResolver=null};using(var r=XmlReader.Create(path,new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null}))d.Load(r);p.Folder=d.SelectSingleNode("/Forma/Folder").InnerText;int.TryParse(d.SelectSingleNode("/Forma/Category").InnerText,out p.Category);var preset=d.SelectSingleNode("/Forma/Preset");if(preset!=null)int.TryParse(preset.InnerText,out p.Preset);for(int i=0;i<5;i++){var n=d.SelectSingleNode("/Forma/Format"+i);if(n!=null)int.TryParse(n.InnerText,out p.Formats[i]);}foreach(var f in typeof(GifOptions).GetFields(BindingFlags.Public|BindingFlags.Instance)){if(f.FieldType!=typeof(string)&&!f.FieldType.IsPrimitive)continue;var n=d.SelectSingleNode("/Forma/Gif/"+f.Name);if(n!=null)f.SetValue(p.Gif,System.Convert.ChangeType(n.InnerText,f.FieldType,CultureInfo.InvariantCulture));}var mode=d.SelectSingleNode("/Forma/LayoutMode");if(mode!=null)int.TryParse(mode.InnerText,out p.LayoutMode);var bitrate=d.SelectSingleNode("/Forma/Mp3Kbps");if(bitrate!=null)int.TryParse(bitrate.InnerText,out p.Mp3Kbps);p.Gif.Validate();p.Gif.AspectRatio();p.Gif.CropRatio();if(p.Gif.Dimension<0||p.Gif.Dimension>1||p.Gif.Method<0||p.Gif.Method>2||p.Gif.Crop< -1)throw new Exception();}catch{p=new Preferences();}p.Category=Math.Max(0,Math.Min(4,p.Category));return p;}
 public void Save(string path){Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(path)));string temp=path+".tmp";using(var w=XmlWriter.Create(temp,new XmlWriterSettings{Indent=true})){w.WriteStartElement("Forma");w.WriteElementString("Folder",Folder);w.WriteElementString("Category",Category.ToString());w.WriteElementString("Preset",Preset.ToString());for(int i=0;i<5;i++)w.WriteElementString("Format"+i,Formats[i].ToString());w.WriteElementString("LayoutMode",LayoutMode.ToString());w.WriteElementString("Mp3Kbps",Mp3Kbps.ToString());w.WriteStartElement("Gif");foreach(var f in typeof(GifOptions).GetFields(BindingFlags.Public|BindingFlags.Instance)){if(f.FieldType!=typeof(string)&&!f.FieldType.IsPrimitive)continue;w.WriteElementString(f.Name,System.Convert.ToString(f.GetValue(Gif),CultureInfo.InvariantCulture));}w.WriteEndElement();w.WriteEndElement();}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}
}

